// ISBN 978-630-342-037-0.
//
// Aici a început clasa a VII-a: recapitularea inițială și Unitatea 1,
// Pe drumul cunoașterii. Școala, până la paronime inclusiv.
// Derivarea, compunerea, locuțiunile, selecția lexicală, limbajul
// popular, fonetica, silaba ca lecție nouă, accentul, limbile vecine,
// proiectul, recapitularea și evaluarea unității nu sunt încă aici.
// Nu copiem fragmente, poezii, citate sau anunțuri cuvânt cu cuvânt.
// Scena de care are nevoie copilul este scrisă în lecție.

function lesson(id, title, block) {
  const example = String(block.example || '').replace(/^Exemplu lucrat:\s*/i, '');
  const platter = [block.theory, `Exemplu lucrat: ${example}`, block.tryThis, block.recap].join('\n\n');
  return {
    id,
    title,
    platter,
    theory: block.theory,
    example,
    tryThis: block.tryThis,
    recap: block.recap
  };
}

